    def _сессия_закрытия_с_метаданными(сам):
        import stat

        корень = сам.каталог / 'корень-закрытия'
        сессия = 'Журнал/2026-09-15_00-00-00_MSK_проверить-поля/запрос.md'
        запрос = корень / сессия
        отчёт = запрос.with_name('отчёт.md')
        каталог = запрос.parent / 'материалы/запуски-проверок'
        снимок = каталог / 'снимок.json'
        сам.удержание['сессия_закрытия'] = (корень, сессия, отчёт, каталог, снимок)
        сам._действие_фикстуры('каталоги сессии', lambda: каталог.mkdir(parents=True))
        сам._действие_фикстуры('синтетический запрос', запрос.write_bytes, b'fixture\n')
        идентификатор = '00000000-0000-4000-8000-000000000001'
        запись = {'схема': 'fum.test-run.v1', 'идентификатор': идентификатор,
                  'сессия': сессия, 'порядок': 1, 'исполнитель': 'фикстура',
                  'вызов': 'проверка', 'состояние': 'завершён',
                  'длительность_наносекунды': 1, 'статус': 'успешно',
                  'код_завершения': 0, 'пояснение': None}
        путь_записи = каталог / ('1_' + идентификатор + '.json')
        содержимое = (json.dumps(запись, ensure_ascii=False) + '\n').encode('utf-8')
        сам._действие_фикстуры('синтетическая запись', путь_записи.write_bytes, содержимое)
        папка_fd = сам._открыть_каталог(запрос.parent)
        сам._задать_список(папка_fd, сам._текст_для_всех(b'allow,file_inherit:execute'))
        fd = сам._открыть(сам.удержание['другие'], отчёт)
        сам._действие_фикстуры('режим отчёта', os.fchmod, fd, 0o755)
        сам.assertEqual(stat.S_IMODE(os.fstat(fd).st_mode), 0o755)
        сам.assertTrue(os.access(отчёт, os.X_OK))
        наследуемый = сам._реальный_список(fd, 1)
        сам.assertEqual(наследуемый[1], ((1, 1, 1),))
        строки = наследуемый[2].splitlines()
        сам.assertEqual(len(строки), 2)
        сам._задать_список(fd, сам._текст_для_всех(b'deny:execute') + строки[1] + b'\n')
        сам.assertFalse(os.access(отчёт, os.X_OK))
        список = сам._реальный_список(fd, 2)
        сам.assertEqual(список[1], ((2, 0, 1), (1, 1, 1)))
        атрибуты = сам.модуль._ВызовыВидимыхАтрибутовДарвина()
        сам.удержание['атрибуты_закрытия'] = атрибуты
        сам._действие_фикстуры('атрибут отчёта', атрибуты.создать, fd,
                                b'com.fum.synthetic', b'\0\xffdata')
        видимые = атрибуты.снять(fd)
        старый = ('До\n' + сам.модуль.ОТКРЫТЫЙ_МАРКЕР + '\nСтарый блок\n'
                  + сам.модуль.КОНЕЧНЫЙ_МАРКЕР + '\nПосле\n').encode('utf-8')
        сам.assertEqual(сам._действие_фикстуры('запись отчёта', os.write, fd, старый), len(старый))
        return корень, сессия, отчёт, снимок, fd, старый, список, атрибуты, видимые

    def _закрыть_сессию_фикстуры(сам, фикстура):
        корень, сессия, *_ = фикстура
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                               return_value=contextlib.nullcontext(lambda: None)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            return сам.модуль.выполнить_закрытие(корень, Path(сессия))

    def _сверить_метаданные_закрытия(сам, фикстура):
        import stat

        _, _, отчёт, снимок, исходный, старый, список, атрибуты, видимые = фикстура
        def открыть():
            return сам.модуль._приобрести_fd(
                сам.удержание['другие'], os.open, отчёт,
                os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
        новый = сам._действие_фикстуры('открытие закрытого отчёта', открыть)
        система = сам.модуль._ВызовыСписковДоступаДарвина()
        сам.удержание['список_закрытого_отчёта'] = система
        данные, _ = система._снять(новый)
        система._освободить_подтверждённые()
        сам.assertEqual((данные == список[0], атрибуты.снять(новый) == видимые), (True, True))
        сам.assertEqual(сам._реальный_список(новый, 2)[1], список[1])
        до, после = os.fstat(исходный), os.fstat(новый)
        сам.assertEqual((после.st_uid, после.st_gid, stat.S_IMODE(после.st_mode)),
                        (до.st_uid, до.st_gid, 0o755))
        сам.assertNotEqual((до.st_dev, до.st_ino), (после.st_dev, после.st_ino))
        сам.assertEqual(os.pread(исходный, len(старый) + 1, 0), старый)
        сам.assertFalse(os.access(отчёт, os.X_OK))
        сам.assertTrue(снимок.is_file())
        сам.assertIn(b'FUM-CHECK-RUNS:BEGIN', os.pread(новый, после.st_size + 1, 0))

    def _повтор_закрытия_запрещён(сам, фикстура, *, корень_алиас=None):
        корень, сессия, *_ = фикстура
        if корень_алиас is not None:
            корень = корень_алиас
        for действие in (сам.модуль.выполнить_закрытие, сам.модуль.выполнить_возобновление):
            with сам.subTest(действие=действие.__name__), \
                 mock.patch.object(сам.модуль, 'межпроцессная_блокировка') as замок, \
                 mock.patch.object(сам.модуль, 'атомарно_записать_байты') as запись, \
                 mock.patch.object(сам.модуль._ОднократнаяЗаписьСнимкаЗакрытия, 'выполнить') as снимок, \
                 mock.patch.object(сам.модуль._ВладелецЗаменыПредпросмотра, 'выполнить') as владелец, \
                 mock.patch.object(os, 'link') as ссылка, mock.patch.object(os, 'replace') as замена, \
                 mock.patch.object(os, 'unlink') as удаление:
                with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'предыдущий исход'):
                    действие(корень, Path(сессия))
            замок.assert_not_called()
            запись.assert_not_called()
            снимок.assert_not_called()
            владелец.assert_not_called()
            ссылка.assert_not_called()
            замена.assert_not_called()
            удаление.assert_not_called()

