    def test_недоступный_список_доступа_отказывает_до_записи_снимка(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, отчёт, снимок, fd, старый, список, атрибуты, видимые = фикстура
        до = os.fstat(fd)
        исходное_чтение = сам.модуль._ВызовыСписковДоступаДарвина._снять
        отказы = []
        def отказ_чтения(система, дескриптор):
            сведения = os.fstat(дескриптор)
            if (сведения.st_dev, сведения.st_ino) == (до.st_dev, до.st_ino):
                отказы.append(True)
                raise OSError(errno.EACCES, 'модель недоступного ACL')
            return исходное_чтение(система, дескриптор)
        with mock.patch.object(сам.модуль._ВызовыСписковДоступаДарвина, '_снять', отказ_чтения), \
             mock.patch.object(сам.модуль._ОднократнаяЗаписьСнимкаЗакрытия, 'выполнить') as запись, \
             mock.patch.object(os, 'replace') as замена, mock.patch.object(os, 'link') as ссылка:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
        сам.assertEqual(отказы, [True])
        запись.assert_not_called()
        замена.assert_not_called()
        ссылка.assert_not_called()
        сам.assertFalse(снимок.exists())
        после = отчёт.lstat()
        сам.assertEqual((до.st_dev, до.st_ino, до.st_mode, до.st_uid, до.st_gid),
                        (после.st_dev, после.st_ino, после.st_mode, после.st_uid, после.st_gid))
        сам.assertEqual(os.pread(fd, len(старый) + 1, 0), старый)
        сам.assertTrue(атрибуты.снять(fd) == видимые)
        наблюдатель = сам.модуль._ВызовыСписковДоступаДарвина()
        сам.удержание['независимая_сверка_списка'] = наблюдатель
        данные, _ = наблюдатель._снять(fd)
        наблюдатель._освободить_подтверждённые()
        сам.assertTrue(данные == список[0])
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')

    def test_неизвестный_снимок_не_повторяет_публикацию_отчёта(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, отчёт, снимок, fd, старый, *_ = фикстура
        атомарно = сам.модуль._ОднократнаяЗаписьСнимкаЗакрытия.выполнить
        эффект = []
        ошибка = OSError(errno.EIO, 'потерян результат снимка')
        def записать_и_потерять(*аргументы, **ключи):
            атомарно(*аргументы, **ключи)
            эффект.append(True)
            raise ошибка
        with mock.patch.object(сам.модуль._ОднократнаяЗаписьСнимкаЗакрытия, 'выполнить', записать_и_потерять), \
             mock.patch.object(os, 'replace', wraps=os.replace) as замена:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
            владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                владелец.выполнить()
        замена.assert_not_called()
        сам.assertEqual(эффект, [True])
        сам.assertTrue(снимок.is_file())
        сам.assertEqual(os.pread(fd, len(старый) + 1, 0), старый)
        сам.assertEqual((отчёт.lstat().st_dev, отчёт.lstat().st_ino),
                        (os.fstat(fd).st_dev, os.fstat(fd).st_ino))
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(владелец.попытка, ('действие после подготовки отчёта', 'начата'))
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_появившийся_снимок_не_перезаписывается(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, отчёт, снимок, fd, старый, *_ = фикстура
        связать = os.link
        события = []
        чужие = b'synthetic existing snapshot'
        def подставить_перед_ссылкой(*аргументы, **ключи):
            события.append('создание начато')
            подставной = сам.модуль._приобрести_fd(
                сам.удержание['другие'], os.open, снимок,
                os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
            сам.assertEqual(os.write(подставной, чужие), len(чужие))
            события.append('создание подтверждено')
            return связать(*аргументы, **ключи)
        with mock.patch.object(os, 'link', side_effect=подставить_перед_ссылкой) as ссылка, \
             mock.patch.object(os, 'replace') as замена, mock.patch.object(os, 'unlink') as удаление:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
        сам.assertEqual(события, ['создание начато', 'создание подтверждено'])
        ссылка.assert_called_once()
        замена.assert_not_called()
        удаление.assert_not_called()
        сам.assertEqual(снимок.read_bytes(), чужие)
        сам.assertEqual(os.pread(fd, len(старый) + 1, 0), старый)
        сам.assertEqual((отчёт.lstat().st_dev, отчёт.lstat().st_ino),
                        (os.fstat(fd).st_dev, os.fstat(fd).st_ino))
        сам.assertEqual(сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1].состояние, 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_потерянная_ссылка_снимка_не_очищается_и_не_повторяется(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
