    def test_другое_написание_каталога_не_обходит_неизвестную_замену(сам):
        try:
            временный = Path('/private/tmp').stat()
            альтернативный = Path('/private/TMP').stat()
        except FileNotFoundError:
            сам.skipTest('на этом томе нет регистрового алиаса временного каталога')
        if (временный.st_dev, временный.st_ino) != (альтернативный.st_dev, альтернативный.st_ino):
            сам.skipTest('регистр пути обозначает другой временный каталог')
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, *_ = фикстура
        алиас = Path('/private/TMP') / корень.relative_to('/private/tmp')
        исходная, альтернативная = корень.stat(), алиас.stat()
        сам.assertNotEqual(str(корень), str(алиас))
        сам.assertEqual((исходная.st_dev, исходная.st_ino), (альтернативная.st_dev, альтернативная.st_ino))
        прямой_отчёт = сам.модуль.разрешить_сессию(корень, Path(сессия))[2]
        отчёт_алиаса = сам.модуль.разрешить_сессию(алиас, Path(сессия))[2]
        if прямой_отчёт == отчёт_алиаса:
            сам.skipTest('разрешение сессии канонизирует регистр; ветка алиаса не проверяется')
        сам.assertEqual(прямой_отчёт.name, отчёт_алиаса.name)
        исходный_родитель, родитель_алиаса = прямой_отчёт.parent.stat(), отчёт_алиаса.parent.stat()
        сам.assertEqual((исходный_родитель.st_dev, исходный_родитель.st_ino),
                        (родитель_алиаса.st_dev, родитель_алиаса.st_ino))
        сам._получить_неизвестную_замену(фикстура)
        сам._повтор_закрытия_запрещён(фикстура)
        сам._повтор_закрытия_запрещён(фикстура, корень_алиас=алиас)

    def test_известный_отказ_после_снимка_допускает_повторное_закрытие(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, отчёт, снимок, fd, старый, *_ = фикстура
        исходный_вызов = сам.модуль._ВладелецЗаменыПредпросмотра._вызвать
        добавление = b'\nsynthetic external edit\n'
        вмешательства = []
        подготовленные_снимки = []
        def отказ(владелец, имя, операция, *аргументы, **ключи):
            if имя == 'повторная проверка предпросмотра' and владелец.действие_подтверждено:
                сведения = снимок.lstat()
                подготовленные_снимки.append(((сведения.st_dev, сведения.st_ino), снимок.read_bytes()))
                вмешательства.append('начато')
                сам.assertEqual(os.pwrite(fd, добавление, len(старый)), len(добавление))
                вмешательства.append('подтверждено')
            return исходный_вызов(владелец, имя, операция, *аргументы, **ключи)
        сам._начать_операцию_фикстуры()
        try:
            with mock.patch.object(сам.модуль._ВладелецЗаменыПредпросмотра, '_вызвать', отказ), \
                 mock.patch.object(os, 'replace', wraps=os.replace) as первая_замена:
                with сам.assertRaises(сам.модуль._ПодтверждённыйОтказПослеСнимка) as исход:
                    сам._закрыть_сессию_фикстуры(фикстура)
            первая_замена.assert_not_called()
            сам.assertEqual(вмешательства, ['начато', 'подтверждено'])
            владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
            сам.assertEqual(владелец.состояние, 'отказ после снимка')
            сам.assertTrue(владелец.действие_подтверждено)
            сам.assertFalse(владелец.замена_начата)
            сам.assertIsNone(владелец._исходный)
            сам.assertIsNone(владелец._временный)
            сам.assertIsNone(владелец._каталог)
            сам.assertIsNone(владелец._родитель)
            сам.assertFalse((отчёт.parent / владелец._имя_каталога).exists())
            сам.assertTrue(снимок.is_file())
            сведения = снимок.lstat()
            сам.assertEqual(((сведения.st_dev, сведения.st_ino), снимок.read_bytes()), подготовленные_снимки[0])
            сам.assertEqual(os.pread(fd, len(старый) + len(добавление) + 1, 0), старый + добавление)
        except BaseException as сбой:
            сам.удержание['состояние'] = 'неизвестно'
            сам.удержание['ошибка'] = сбой
            raise
        сам.удержание['состояние'] = 'готово'
        with mock.patch.object(os, 'replace', wraps=os.replace) as повторная_замена:
            результат = сам._действие_фикстуры('повторное закрытие', сам._закрыть_сессию_фикстуры, фикстура)
        повторная_замена.assert_called_once()
        сам.assertEqual(результат, 0)
        сведения = снимок.lstat()
        сам.assertEqual(((сведения.st_dev, сведения.st_ino), снимок.read_bytes()), подготовленные_снимки[0])
        фикстура = (*фикстура[:5], старый + добавление, *фикстура[6:])
        сам._сверить_метаданные_закрытия(фикстура)

    def test_одновременная_подмена_отчёта_и_снимка_остаётся_неизвестной(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, _, снимок, fd, старый, *_ = фикстура
        исходный_вызов = сам.модуль._ВладелецЗаменыПредпросмотра._вызвать
        удалить = os.unlink
        изменения, удаления = [], []
        def подменить(владелец, имя, операция, *аргументы, **ключи):
            if имя == 'повторная проверка предпросмотра' and владелец.действие_подтверждено:
                изменения.append('отчёт начат')
                сам.assertEqual(os.pwrite(fd, b'X', len(старый)), 1)
                изменения.append('отчёт подтверждён')
                снимок_fd = сам.модуль._приобрести_fd(
                    сам.удержание['другие'], os.open, снимок,
                    os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC)
                изменения.append('снимок начат')
                сам.assertEqual(os.pwrite(снимок_fd, b'X', os.fstat(снимок_fd).st_size), 1)
                изменения.append('снимок подтверждён')
            return исходный_вызов(владелец, имя, операция, *аргументы, **ключи)
        def наблюдать_удаление(путь, *аргументы, **ключи):
            if путь == 'отчёт' and ключи.get('dir_fd') is not None:
                удаления.append(True)
                raise AssertionError('неожиданная очистка подготовленного отчёта')
            return удалить(путь, *аргументы, **ключи)
        with mock.patch.object(сам.модуль._ВладелецЗаменыПредпросмотра, '_вызвать', подменить), \
             mock.patch.object(os, 'unlink', side_effect=наблюдать_удаление), \
             mock.patch.object(os, 'replace') as замена:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
        сам.assertEqual(изменения, ['отчёт начат', 'отчёт подтверждён',
                                    'снимок начат', 'снимок подтверждён'])
        сам.assertEqual(удаления, [])
        замена.assert_not_called()
        владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_потеря_замка_после_снимка_не_публикует_отчёт(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, отчёт, снимок, fd, старый, *_ = фикстура
        проверки, удаления = [], []
        удалить = os.unlink
        def сверить():
            if снимок.exists():
                проверки.append('после снимка')
                raise сам.модуль.ОшибкаОтчёта('модель потери замка')
            проверки.append('до снимка')
        def наблюдать_удаление(путь, *аргументы, **ключи):
            if путь == 'отчёт' and ключи.get('dir_fd') is not None:
                удаления.append(True)
                raise AssertionError('неожиданная очистка подготовленного отчёта')
            return удалить(путь, *аргументы, **ключи)
        def закрыть():
            return сам.модуль.выполнить_закрытие(корень, Path(сессия))
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                               return_value=contextlib.nullcontext(сверить)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(os, 'unlink', side_effect=наблюдать_удаление), \
             mock.patch.object(os, 'replace') as замена:
            with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'модель потери замка'):
                сам._действие_фикстуры('закрытие', закрыть)
        сам.assertIn('до снимка', проверки)
        сам.assertEqual(проверки[-1], 'после снимка')
        сам.assertEqual(удаления, [])
        замена.assert_not_called()
        сам.assertTrue(снимок.is_file())
        сам.assertEqual(os.pread(fd, len(старый) + 1, 0), старый)
        сам.assertEqual((отчёт.lstat().st_dev, отчёт.lstat().st_ino),
                        (os.fstat(fd).st_dev, os.fstat(fd).st_ino))
        владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
        сам.assertTrue(владелец.действие_подтверждено)
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_отказ_очистки_после_снимка_остаётся_неизвестным(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, _, снимок, fd, старый, *_ = фикстура
        исходный_вызов = сам.модуль._ВладелецЗаменыПредпросмотра._вызвать
        удалить = os.unlink
        добавление = b'\nsynthetic external edit\n'
        вмешательства = []
        ошибка_очистки = OSError(errno.EIO, 'неизвестный исход очистки')
        попытки = []
        def отказ(владелец, имя, операция, *аргументы, **ключи):
            if имя == 'повторная проверка предпросмотра' and владелец.действие_подтверждено:
                вмешательства.append('начато')
                сам.assertEqual(os.pwrite(fd, добавление, len(старый)), len(добавление))
                вмешательства.append('подтверждено')
            return исходный_вызов(владелец, имя, операция, *аргументы, **ключи)
        def отказ_удаления(путь, *аргументы, **ключи):
            if путь == 'отчёт' and ключи.get('dir_fd') is not None:
                попытки.append(True)
                raise ошибка_очистки
            return удалить(путь, *аргументы, **ключи)
        with mock.patch.object(сам.модуль._ВладелецЗаменыПредпросмотра, '_вызвать', отказ), \
             mock.patch.object(os, 'unlink', side_effect=отказ_удаления):
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта) as исход:
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
            владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                владелец.выполнить()
        сам.assertEqual(попытки, [True])
        сам.assertEqual(вмешательства, ['начато', 'подтверждено'])
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertIsInstance(владелец.первичная, сам.модуль._ПодтверждённыйОтказПослеСнимка)
        сам.assertIs(владелец.ошибка, ошибка_очистки)
        сам.assertIsInstance(исход.exception.__cause__, ExceptionGroup)
        сам.assertEqual(исход.exception.__cause__.exceptions, (владелец.первичная, ошибка_очистки))
        сам.assertTrue(снимок.is_file())
        сам.assertEqual(os.pread(fd, len(старый) + len(добавление) + 1, 0), старый + добавление)
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')

