    def test_подмена_истории_на_git_профиль_под_замком_отклоняется(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, отчёт, снимок, *_ = фикстура
        запись = next(снимок.parent.glob('1_*.json'))
        значение = json.loads(запись.read_bytes())
        значение.update({'схема': 'fum.test-run.v3', 'план': None, 'наблюдения': [],
            'профиль_проверки': {'класс': 'адресная', 'отпечаток_снимка': 'sha256:' + '0' * 64,
                'полные_наборы': [], 'основание': None, 'идентификатор_отказа': None,
                'ожидаемое_свидетельство': None}})
        байты = сам.модуль.канонические_машинные_байты(значение)
        читать = сам.модуль.прочитать_записи
        настоящий_замок = сам.модуль.межпроцессная_блокировка
        замок_активен = [False]
        чтения = []
        @contextlib.contextmanager
        def наблюдать_настоящий_замок(*аргументы, **ключи):
            with настоящий_замок(*аргументы, **ключи) as сверить:
                замок_активен[0] = True
                try:
                    yield сверить
                finally:
                    замок_активен[0] = False
        def подменить_перед_повторным_чтением(*аргументы, **ключи):
            чтения.append(замок_активен[0])
            if len(чтения) == 2:
                запись.write_bytes(байты)
            return читать(*аргументы, **ключи)
        до = отчёт.read_bytes()
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(сам.модуль, 'межпроцессная_блокировка', наблюдать_настоящий_замок), \
             mock.patch.object(сам.модуль, 'прочитать_записи', side_effect=подменить_перед_повторным_чтением), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(os, 'link', side_effect=AssertionError('ссылка до отказа')), \
             mock.patch.object(os, 'replace', side_effect=AssertionError('замена до отказа')):
            with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'профиль исторического Git-снимка неизвестен'):
                сам.модуль.выполнить_возобновление(корень, Path(сессия))
        сам.assertEqual(чтения, [False, True])
        сам.assertFalse(сам.модуль._ВладелецВозобновления._удерживаемые)
        сам.assertEqual(отчёт.read_bytes(), до)
        сам.assertFalse(снимок.exists())

