    def _проверить_появление_снимка_при_восстановлении_журнала(сам, момент):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        настоящий_fsync, настоящий_link = os.fsync, os.link
        настоящий_вызов = сам.модуль._ОднократнаяЗаписьМашинногоФайла._вызвать
        сбой = OSError(errno.EIO, 'сбой синхронизации удаления журнала')
        отказы, попытки_ссылки, появления = [], [], []
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            байты_снимка = снимок.read_bytes()
            каталог = снимок.parent.stat()
            def вернуть_снимок():
                снимок.write_bytes(байты_снимка)
                появления.append(True)
            def сбой_fsync(fd):
                сведения = os.fstat(fd)
                if ((сведения.st_dev, сведения.st_ino) == (каталог.st_dev, каталог.st_ino)
                    and not снимок.exists() and not журнал.exists() and not отказы):
                    отказы.append(True)
                    if момент == 'до сверки':
                        вернуть_снимок()
                    raise сбой
                return настоящий_fsync(fd)
            def отследить_link(источник, назначение, *аргументы, **ключи):
                if отказы and назначение == журнал.name:
                    попытки_ссылки.append(True)
                    raise AssertionError('запрещённая повторная публикация')
                return настоящий_link(источник, назначение, *аргументы, **ключи)
            def вызов(владелец, имя, операция, *аргументы, **ключи):
                if (отказы and момент == 'перед публикацией' and владелец.путь == журнал
                    and имя == 'проверка перед публикацией журнала возобновления'):
                    вернуть_снимок()
                return настоящий_вызов(владелец, имя, операция, *аргументы, **ключи)
            with mock.patch.object(os, 'fsync', side_effect=сбой_fsync), \
                 mock.patch.object(os, 'link', side_effect=отследить_link), \
                 mock.patch.object(сам.модуль._ОднократнаяЗаписьМашинногоФайла, '_вызвать', вызов):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertEqual((отказы, появления, попытки_ссылки), ([True], [True], []))
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам.assertEqual(сам.модуль._ВладелецВозобновления._удерживаемые[-1].состояние, 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

