    def test_подтверждённое_восстановление_журнала_после_fsync_допускает_повтор(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, отчёт, снимок, _, _, список, атрибуты, видимые = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        fsync = os.fsync
        сбой = OSError(errno.EIO, 'сбой синхронизации удаления журнала')
        отказы = []
        вызов_записи = сам.модуль._ОднократнаяЗаписьМашинногоФайла._вызвать
        выполнить_запись = сам.модуль._ОднократнаяЗаписьМашинногоФайла.выполнить
        удержать = сам.модуль._удержать_файл_перед_удалением
        закрыть = os.close
        фазы_восстановления = []
        заимствованный, закрытия_опоры = [], []
        опора_активна = [False]
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            каталог = снимок.parent.stat()
            def отказ_fsync(fd):
                сведения = os.fstat(fd)
                if ((сведения.st_dev, сведения.st_ino) == (каталог.st_dev, каталог.st_ino)
                    and not снимок.exists() and not журнал.exists() and not отказы):
                    отказы.append(True)
                    raise сбой
                return fsync(fd)
            def отметить_восстановление(владелец, имя, операция, *аргументы, **ключи):
                if отказы and владелец.путь == журнал:
                    if имя == 'проверка перед публикацией журнала возобновления':
                        сведения = os.fstat(владелец.каталог_fd)
                        сам.assertEqual((сведения.st_dev, сведения.st_ino), (каталог.st_dev, каталог.st_ino))
                        сам.assertEqual(владелец.опора_каталога, заимствованный[0])
                        сам.assertNotEqual(владелец.каталог_fd, владелец.опора_каталога)
                    фазы_восстановления.append(имя)
                return вызов_записи(владелец, имя, операция, *аргументы, **ключи)
            @contextlib.contextmanager
            def наблюдать_удержание(путь, *аргументы, **ключи):
                with удержать(путь, *аргументы, **ключи) as пара:
                    if путь == журнал:
                        заимствованный.append(пара[0])
                        опора_активна[0] = True
                    yield пара
                if путь == журнал:
                    опора_активна[0] = False
                    with сам.assertRaises(OSError) as исход:
                        os.fstat(пара[0])
                    сам.assertEqual(исход.exception.errno, errno.EBADF)
            def наблюдать_close(fd):
                if опора_активна[0] and заимствованный and fd == заимствованный[0]:
                    закрытия_опоры.append(fd)
                return закрыть(fd)
            def выполнить_восстановление(владелец):
                if not отказы or владелец.путь != журнал:
                    return выполнить_запись(владелец)
                сам.assertIs(сам.модуль._ВладелецВозобновления._удерживаемые[-1].восстановление_журнала,
                             владелец)
                итог = выполнить_запись(владелец)
                сам.assertIsNone(владелец.каталог_fd)
                сам.assertIsNone(владелец.файл_fd)
                сведения = os.fstat(владелец.опора_каталога)
                сам.assertEqual((сведения.st_dev, сведения.st_ino), (каталог.st_dev, каталог.st_ino))
                return итог
            with mock.patch.object(os, 'fsync', side_effect=отказ_fsync), \
                 mock.patch.object(os, 'close', side_effect=наблюдать_close), \
                 mock.patch.object(сам.модуль, '_удержать_файл_перед_удалением', наблюдать_удержание), \
                 mock.patch.object(сам.модуль._ОднократнаяЗаписьМашинногоФайла, 'выполнить', выполнить_восстановление), \
                 mock.patch.object(сам.модуль._ОднократнаяЗаписьМашинногоФайла, '_вызвать', отметить_восстановление):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта) as исход:
                    сам.модуль.выполнить_возобновление(корень, Path(сессия))
            сам.assertIs(исход.exception.__cause__, сбой)
            сам.assertEqual(отказы, [True])
            сам.assertEqual(фазы_восстановления.count('публикация нового журнала возобновления'), 1)
            сам.assertEqual(фазы_восстановления.count('синхронизация очистки журнала возобновления'), 1)
            сам.assertEqual(закрытия_опоры, заимствованный)
            сам.assertEqual(len(закрытия_опоры), 1)
            сам.assertFalse(сам.модуль._ВладелецВозобновления._удерживаемые)
            сам.assertFalse(снимок.exists())
            сам.assertTrue(журнал.is_file())
            открытый = отчёт.stat()
            fd = сам._действие_фикстуры('открытие подтверждённого отчёта',
                lambda: сам.модуль._приобрести_fd(сам.удержание['другие'], os.open, отчёт,
                    os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC))
            with mock.patch.object(os, 'replace', side_effect=AssertionError('повторная замена')):
                сам.assertEqual(сам._действие_фикстуры(
                    'завершение восстановленного журнала', сам.модуль.выполнить_возобновление,
                    корень, Path(сессия)), 0)
        после = отчёт.stat()
        сам.assertEqual((открытый.st_dev, открытый.st_ino), (после.st_dev, после.st_ino))
        сам.assertEqual(атрибуты.снять(fd), видимые)
        сам.assertEqual(сам._реальный_список(fd, 2)[0:2], список[0:2])
        сам.assertFalse(журнал.exists())

    def _проверить_неизвестное_восстановление_журнала(сам, этап):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        fsync, link, close = os.fsync, os.link, os.close
        отказ_fsync = OSError(errno.EIO, 'сбой синхронизации удаления журнала')
        потеря = OSError(errno.EIO, 'потерян результат восстановления')
        отказы, эффекты = [], []
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            каталог = снимок.parent.stat()
            def сбой_fsync(fd):
                сведения = os.fstat(fd)
                if ((сведения.st_dev, сведения.st_ino) == (каталог.st_dev, каталог.st_ino)
                    and not снимок.exists() and not журнал.exists() and not отказы):
                    отказы.append(True)
                    raise отказ_fsync
                return fsync(fd)
            def потерять_link(источник, назначение, *аргументы, **ключи):
                if этап == 'link' and отказы and назначение == журнал.name:
                    link(источник, назначение, *аргументы, **ключи)
                    эффекты.append(True)
                    raise потеря
                return link(источник, назначение, *аргументы, **ключи)
            def потерять_close(fd):
                владельцы = сам.модуль._ВладелецВозобновления._удерживаемые
                восстановление = getattr(владельцы[-1], 'восстановление_журнала', None) if владельцы else None
                if (этап == 'close' and отказы and восстановление is not None
                    and восстановление.файл_fd == fd):
                    close(fd)
                    эффекты.append(True)
                    raise потеря
                return close(fd)
            with mock.patch.object(os, 'fsync', side_effect=сбой_fsync), \
                 mock.patch.object(os, 'link', side_effect=потерять_link), \
                 mock.patch.object(os, 'close', side_effect=потерять_close):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта) as исход:
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertEqual((отказы, эффекты), ([True], [True]))
        владелец = сам.модуль._ВладелецВозобновления._удерживаемые[-1]
        восстановление = владелец.восстановление_журнала
        сам.assertEqual((владелец.состояние, восстановление.состояние), ('неизвестно', 'неизвестно'))
        сам.assertIs(владелец.ошибка_удаления_журнала, отказ_fsync)
        сам.assertIs(восстановление.ошибка, потеря)
        сам.assertIsInstance(исход.exception.__cause__, BaseExceptionGroup)
        сам.assertEqual(исход.exception.__cause__.exceptions, (отказ_fsync, потеря))
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

