    def test_подмена_каталога_восстановления_отклоняется_до_temp(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        исходный_вызов = сам.модуль._ОднократнаяЗаписьМашинногоФайла._вызвать
        fsync, открыть = os.fsync, os.open
        отказы, подмены, открытия = [], [], []
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            каталог = снимок.parent.stat()
            старый_каталог = снимок.parent.with_name('синтетическая-старая-папка')
            def отказ_fsync(fd):
                сведения = os.fstat(fd)
                if ((сведения.st_dev, сведения.st_ino) == (каталог.st_dev, каталог.st_ino)
                    and not снимок.exists() and not журнал.exists() and not отказы):
                    отказы.append(True)
                    raise OSError(errno.EIO, 'сбой синхронизации удаления журнала')
                return fsync(fd)
            def подменить_каталог(владелец, имя, операция, *аргументы, **ключи):
                результат = исходный_вызов(владелец, имя, операция, *аргументы, **ключи)
                if (отказы and not подмены and владелец.путь == журнал
                    and имя == 'проверка перед подготовкой журнала возобновления'):
                    os.rename(снимок.parent, старый_каталог)
                    os.mkdir(снимок.parent, 0o700)
                    подмены.append(True)
                return результат
            def отследить_temp(имя, флаги, *аргументы, **ключи):
                if (подмены and isinstance(имя, str) and имя.startswith('.' + журнал.name + '.')
                    and флаги & os.O_CREAT):
                    открытия.append(True)
                    raise AssertionError('открытие temp в подменённом каталоге')
                return открыть(имя, флаги, *аргументы, **ключи)
            with mock.patch.object(os, 'fsync', side_effect=отказ_fsync), \
                 mock.patch.object(os, 'open', side_effect=отследить_temp), \
                 mock.patch.object(сам.модуль._ОднократнаяЗаписьМашинногоФайла, '_вызвать', подменить_каталог):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertEqual((отказы, подмены, открытия), ([True], [True], []))
        владелец = сам.модуль._ВладелецВозобновления._удерживаемые[-1]
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(владелец.восстановление_журнала.состояние, 'неизвестно')
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_ошибка_после_успешного_fsync_не_запускает_восстановление(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        fsync, stat, link = os.fsync, os.stat, os.link
        завершено, отказы, попытки = [], [], []
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            метка_каталога = снимок.parent.stat()
            def наблюдать_fsync(fd):
                сведения = os.fstat(fd)
                итог = fsync(fd)
                if ((сведения.st_dev, сведения.st_ino) == (метка_каталога.st_dev, метка_каталога.st_ino)
                    and not снимок.exists() and not журнал.exists() and not завершено):
                    завершено.append(True)
                return итог
            def отказ_stat(имя, *аргументы, **ключи):
                if завершено and имя == журнал.name and ключи.get('dir_fd') is not None and not отказы:
                    отказы.append(True)
                    raise OSError(errno.EIO, 'сбой после успешного fsync')
                return stat(имя, *аргументы, **ключи)
            def запретить_link(источник, назначение, *аргументы, **ключи):
                if завершено and назначение == журнал.name:
                    попытки.append(True)
                    raise AssertionError('повторная публикация журнала')
                return link(источник, назначение, *аргументы, **ключи)
            with mock.patch.object(os, 'fsync', side_effect=наблюдать_fsync), \
                 mock.patch.object(os, 'stat', side_effect=отказ_stat), \
                 mock.patch.object(os, 'link', side_effect=запретить_link):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertEqual((завершено, отказы, попытки), ([True], [True], []))
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_появившийся_снимок_запрещает_восстановление_журнала(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        fsync, link, replace = os.fsync, os.link, os.replace
        отказы, попытки = [], []
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            байты_снимка = снимок.read_bytes()
            каталог = снимок.parent.stat()
            def вернуть_снимок_при_отказе(fd):
                сведения = os.fstat(fd)
                if ((сведения.st_dev, сведения.st_ino) == (каталог.st_dev, каталог.st_ino)
                    and not снимок.exists() and not журнал.exists() and not отказы):
                    снимок.write_bytes(байты_снимка)
                    отказы.append(True)
                    raise OSError(errno.EIO, 'снимок появился при отказе fsync')
                return fsync(fd)
            def отметить(операция, источник, назначение, *аргументы, **ключи):
                if отказы and os.path.basename(os.fspath(назначение)) == журнал.name:
                    попытки.append(True)
                return операция(источник, назначение, *аргументы, **ключи)
            with mock.patch.object(os, 'fsync', side_effect=вернуть_снимок_при_отказе), \
                 mock.patch.object(os, 'link', side_effect=lambda *а, **к: отметить(link, *а, **к)), \
                 mock.patch.object(os, 'replace', side_effect=lambda *а, **к: отметить(replace, *а, **к)):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertEqual(отказы, [True])
        сам.assertEqual(попытки, [])
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def test_отмена_при_восстановлении_журнала_не_маскируется(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        fsync, link = os.fsync, os.link
        выполнить_запись = сам.модуль._ОднократнаяЗаписьМашинногоФайла.выполнить
        отказ = OSError(errno.EIO, 'сбой синхронизации удаления журнала')
        отмена = KeyboardInterrupt('отмена восстановления журнала')
        отказы, попытки, отмены = [], [], []
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            метка_каталога = снимок.parent.stat()
            def отказ_fsync(fd):
                сведения = os.fstat(fd)
                if ((сведения.st_dev, сведения.st_ino) == (метка_каталога.st_dev, метка_каталога.st_ino)
                    and not снимок.exists() and not журнал.exists() and not отказы):
                    отказы.append(True)
                    raise отказ
                return fsync(fd)
            def запретить_link(источник, назначение, *аргументы, **ключи):
                if отказы and назначение == журнал.name:
                    попытки.append(True)
                    raise AssertionError('повторная публикация журнала')
                return link(источник, назначение, *аргументы, **ключи)
            def отменить_запись(владелец):
                if владелец.путь == журнал and отказы:
                    отмены.append(True)
                    raise отмена
                return выполнить_запись(владелец)
            with mock.patch.object(os, 'fsync', side_effect=отказ_fsync), \
                 mock.patch.object(os, 'link', side_effect=запретить_link), \
                 mock.patch.object(сам.модуль._ОднократнаяЗаписьМашинногоФайла, 'выполнить', отменить_запись):
                with сам.assertRaises(KeyboardInterrupt) as исход:
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertIs(исход.exception, отмена)
        сам.assertIs(отмена.__cause__, отказ)
        сам.assertEqual((отказы, отмены, попытки), ([True], [True], []))
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

    def _проверить_отмену_сверки_после_отказа_unlink(сам, имя_фазы, тип_отмены=KeyboardInterrupt):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        цель = снимок if имя_фазы == 'снимок' else журнал
        удалить = os.unlink
        удержать = сам.модуль._удержать_файл_перед_удалением
        отказ = OSError(errno.EACCES, 'отказ до удаления')
        отмена = тип_отмены('прерывание вторичной сверки')
        отказы, отмены = [], []
        def отказ_unlink(имя, *аргументы, **ключи):
            if имя == цель.name and ключи.get('dir_fd') is not None:
                отказы.append(True)
                raise отказ
            return удалить(имя, *аргументы, **ключи)
        @contextlib.contextmanager
        def с_прерыванием(путь, *аргументы, **ключи):
            with удержать(путь, *аргументы, **ключи) as (fd, проверить):
                счётчик = []
                def проверить_с_отменой():
                    счётчик.append(True)
                    if путь == цель and len(счётчик) == 2:
                        отмены.append(True)
                        raise отмена
                    проверить()
                yield fd, проверить_с_отменой
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            with mock.patch.object(os, 'unlink', side_effect=отказ_unlink), \
                 mock.patch.object(сам.модуль, '_удержать_файл_перед_удалением', с_прерыванием):
                with сам.assertRaises(тип_отмены) as исход:
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertIs(исход.exception, отмена)
        сам.assertIs(отмена.__cause__, отказ)
        сам.assertEqual((отказы, отмены), ([True], [True]))
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам.assertEqual(сам.модуль._ВладелецВозобновления._удерживаемые[-1].состояние, 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

