    def _проверить_двойной_отказ_удержания(сам, отмена_в_close, *, журнал=False):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, _, снимок, *_ = фикстура
        цель = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ if журнал else снимок
        удалить, закрыть = os.unlink, os.close
        удержать = сам.модуль._удержать_файл_перед_удалением
        исходный_отказ = OSError(errno.EACCES, 'отказ до удаления снимка')
        прежняя_причина = ValueError('прежняя причина отмены')
        отмена = SystemExit('отмена close') if отмена_в_close else KeyboardInterrupt('отмена сверки')
        if отмена_в_close:
            отмена.__cause__ = прежняя_причина
        ошибка_close = отмена if отмена_в_close else OSError(errno.EIO, 'неизвестный close')
        целевые_fd, попытки_close = [], []
        def отказ_unlink(имя, *аргументы, **ключи):
            if имя == цель.name and ключи.get('dir_fd') is not None:
                raise исходный_отказ
            return удалить(имя, *аргументы, **ключи)
        @contextlib.contextmanager
        def контролируемое_удержание(путь, *аргументы, **ключи):
            with удержать(путь, *аргументы, **ключи) as (fd, проверить):
                счётчик = []
                if путь == цель:
                    целевые_fd.append(fd)
                def проверить_снимок():
                    счётчик.append(True)
                    if путь == цель and len(счётчик) == 2 and not отмена_в_close:
                        raise отмена
                    проверить()
                yield fd, проверить_снимок
        def закрыть_с_отказом(fd):
            if fd in целевые_fd:
                попытки_close.append(fd)
                закрыть(fd)
                raise ошибка_close
            return закрыть(fd)
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            with mock.patch.object(os, 'unlink', side_effect=отказ_unlink), \
                 mock.patch.object(os, 'close', side_effect=закрыть_с_отказом), \
                 mock.patch.object(сам.модуль, '_удержать_файл_перед_удалением', контролируемое_удержание):
                with сам.assertRaises(type(отмена)) as исход:
                    сам._действие_фикстуры(
                        'возобновление', сам.модуль.выполнить_возобновление, корень, Path(сессия))
        сам.assertIs(исход.exception, отмена)
        сам.assertEqual(попытки_close, целевые_fd)
        сам.assertEqual(len(попытки_close), 1)
        владелец = сам.модуль._ВладелецВозобновления._удерживаемые[-1]
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertIs(владелец.ошибка_удаления_журнала if журнал else владелец.ошибка_удаления_снимка,
                     исходный_отказ)
        запись = сам.модуль._неизвестные_закрытия_fd[-1]
        сам.assertIn(ошибка_close, запись['ошибки'])
        if отмена_в_close:
            сам.assertIs(отмена.__cause__, прежняя_причина)
        else:
            сам.assertIs(отмена.__cause__, исходный_отказ)
            сам.assertIs(запись['первичная'], отмена)
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')
        сам._повтор_закрытия_запрещён(фикстура)

