    def test_закрытый_отчёт_со_спецбитом_отклоняется_до_журнала_и_допускает_исправление(сам):
        import stat

        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, отчёт, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            fd = сам._действие_фикстуры('открытие закрытого отчёта',
                lambda: сам.модуль._приобрести_fd(сам.удержание['другие'], os.open, отчёт,
                    os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC))
            сам._действие_фикстуры('установка спецбита', os.fchmod, fd, 0o4755)
            сам.assertEqual(stat.S_IMODE(os.fstat(fd).st_mode), 0o4755)
            до = отчёт.stat()
            снимок_до, снимок_байты = снимок.stat(), снимок.read_bytes()
            with mock.patch.object(os, 'replace', side_effect=AssertionError('замена при отказе')):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                    сам.модуль.выполнить_возобновление(корень, Path(сессия))
            сам.assertFalse(журнал.exists())
            сам.assertEqual((до.st_dev, до.st_ino, stat.S_IMODE(до.st_mode)),
                            (отчёт.stat().st_dev, отчёт.stat().st_ino, 0o4755))
            сам.assertEqual((снимок_до.st_dev, снимок_до.st_ino, снимок_байты),
                            (снимок.stat().st_dev, снимок.stat().st_ino, снимок.read_bytes()))
            сам.assertFalse(сам.модуль._ВладелецВозобновления._удерживаемые)
            сам._действие_фикстуры('исправление режима', os.fchmod, fd, 0o755)
            сам.assertEqual(сам._действие_фикстуры(
                'возобновление после исправления', сам.модуль.выполнить_возобновление,
                корень, Path(сессия)), 0)

    def test_недоступный_acl_возобновления_отказывает_до_создания_журнала(сам):
        фикстура = сам._сессия_закрытия_с_метаданными()
        корень, сессия, отчёт, снимок, *_ = фикстура
        журнал = снимок.parent / сам.модуль.ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(subprocess, 'run', side_effect=AssertionError('неожиданный процесс')), \
             mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('неожиданный процесс')):
            сам.assertEqual(сам._действие_фикстуры(
                'закрытие', сам.модуль.выполнить_закрытие, корень, Path(сессия)), 0)
            отчёт_до, байты_отчёта = отчёт.stat(), отчёт.read_bytes()
            снимок_до, байты_снимка = снимок.stat(), снимок.read_bytes()
            читать_acl = сам.модуль._ВызовыСписковДоступаДарвина._снять
            отказы = []
            def отказ_acl(система, fd):
                сведения = os.fstat(fd)
                if (сведения.st_dev, сведения.st_ino) == (отчёт_до.st_dev, отчёт_до.st_ino):
                    отказы.append(True)
