    def test_подмена_отчёта_ссылкой_до_открытия_не_читает_цель(сам):
        import io

        for стадия, номер in (('исходное чтение', 1), ('проверка перед публикацией', 2)):
            with сам.subTest(стадия=стадия):
                корень, сессия, отчёт, _, _ = сам._синтетическая_сессия()
                цель = корень / 'синтетическая-цель'
                цель.write_bytes(b'synthetic target')
                метка_цели = цель.stat()
                сохранённый = отчёт.with_name('исходный-файл')
                штатное_открытие = os.open
                штатный_поток = io.open
                штатное_чтение = os.read
                штатный_stat = os.stat
                открытия, чтения_цели, подмены, отметки = [], [], [], []
                class ПредотвращеноЧтениеЦели(Exception):
                    pass
                def получить_метку(путь, *аргументы, **ключи):
                    результат = штатный_stat(путь, *аргументы, **ключи)
                    владельцы = сам.модуль._ЗакреплённыеКаталогиПредпросмотра._удерживаемые
                    if (путь == отчёт.name and владельцы
                        and ключи.get('dir_fd') == владельцы[-1]._родитель):
                        отметки.append(True)
                        if len(отметки) == 2 * номер - 1:
                            отчёт.rename(сохранённый)
                            отчёт.symlink_to(цель)
                            подмены.append(True)
                    return результат
                def открыть(путь, флаги, *аргументы, **ключи):
                    имя = os.fspath(путь) if isinstance(путь, (str, bytes, os.PathLike)) else None
                    if имя == os.fspath(цель):
                        чтения_цели.append('открытие цели')
                        raise ПредотвращеноЧтениеЦели()
                    владельцы = сам.модуль._ЗакреплённыеКаталогиПредпросмотра._удерживаемые
                    if (имя == отчёт.name and владельцы
                        and ключи.get('dir_fd') == владельцы[-1]._родитель):
                        открытия.append(флаги)
                    return штатное_открытие(путь, флаги, *аргументы, **ключи)
                def поток(путь, режим='r', *аргументы, **ключи):
                    имя = os.fspath(путь) if isinstance(путь, (str, bytes, os.PathLike)) else None
                    if подмены and имя in (os.fspath(отчёт), os.fspath(цель)):
                        чтения_цели.append('поток цели')
                        raise ПредотвращеноЧтениеЦели()
                    return штатный_поток(путь, режим, *аргументы, **ключи)
                def читать(fd, размер):
                    сведения = os.fstat(fd)
                    if (сведения.st_dev, сведения.st_ino) == (метка_цели.st_dev, метка_цели.st_ino):
                        чтения_цели.append('чтение цели')
                        raise ПредотвращеноЧтениеЦели()
                    return штатное_чтение(fd, размер)
                with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                                       return_value=contextlib.nullcontext(lambda: None)), \
                     mock.patch.object(os, 'stat', side_effect=получить_метку), \
                     mock.patch.object(os, 'open', side_effect=открыть), \
                     mock.patch.object(os, 'read', side_effect=читать), \
                     mock.patch.object(io, 'open', side_effect=поток), \
                     mock.patch.object(os, 'replace', wraps=os.replace) as замена:
                    try:
                        сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
                    except (сам.модуль.ОшибкаОтчёта, ПредотвращеноЧтениеЦели):
                        pass
                    else:
                        сам.fail('подмена отчёта не отклонена')
                сам.assertEqual(подмены, [True])
                сам.assertEqual(чтения_цели, [])
                сам.assertEqual(len(открытия), номер)
                сам.assertTrue(all(флаги & os.O_NOFOLLOW and флаги & os.O_NONBLOCK
                                   for флаги in открытия))
                замена.assert_not_called()
                сам.assertTrue(отчёт.is_symlink())
                сам.assertEqual(сохранённый.read_bytes(), сам.старый)
                после_цели = цель.lstat()
                сам.assertEqual((после_цели.st_dev, после_цели.st_ino, после_цели.st_size),
                                (метка_цели.st_dev, метка_цели.st_ino, метка_цели.st_size))

    def test_подмена_предка_не_даёт_читать_чужой_отчёт_или_историю(сам):
        import io

        варианты = (('отчёт', 1), ('история', 1), ('история', 2),
                    ('история', 3), ('отчёт', 2))
        for вид, номер in варианты:
            with сам.subTest(вид=вид, номер=номер):
                корень, сессия, отчёт, путь_записи, _ = сам._синтетическая_сессия()
                журнал = корень / 'Журнал'
                сохранённый = корень / 'сохранённый-журнал'
                цель = корень / 'синтетическая-цель'
                цель_сессии = цель / отчёт.parent.name
                цель_записей = цель_сессии / 'материалы' / 'запуски-проверок'
                цель_записей.mkdir(parents=True)
                цель_отчёта = цель_сессии / отчёт.name
                цель_записи = цель_записей / путь_записи.name
                цель_отчёта.write_bytes(b'synthetic report target')
                цель_записи.write_bytes(b'synthetic history target')
                метки_целей = {
                    (сведения.st_dev, сведения.st_ino)
                    for сведения in (цель_отчёта.stat(), цель_записи.stat())
                }
                штатное_открытие = os.open
                штатный_поток = io.open
                штатное_чтение = os.read
                штатный_pread = os.pread
                открытия, подмены, чтения_цели = [], [], []
                class ПредотвращеноЧтениеЦели(Exception):
                    pass
                def открыть(путь, флаги, *аргументы, **ключи):
                    имя = os.fspath(путь) if isinstance(путь, (str, bytes, os.PathLike)) else None
                    fd = ключи.get('dir_fd')
                    владельцы = getattr(сам.модуль, '_ЗакреплённыеКаталогиПредпросмотра', None)
                    владельцы = [] if владельцы is None else владельцы._удерживаемые
                    ожидаемое_имя = отчёт.name if вид == 'отчёт' else путь_записи.name
                    ожидаемый_fd = None
                    if владельцы:
                        ожидаемый_fd = владельцы[-1]._родитель if вид == 'отчёт' else владельцы[-1]._запуски
                    абсолютный = os.fspath(отчёт if вид == 'отчёт' else путь_записи)
                    if имя == абсолютный or (имя == ожидаемое_имя and fd == ожидаемый_fd and fd is not None):
                        открытия.append(флаги)
                        if len(открытия) == номер:
                            журнал.rename(сохранённый)
                            журнал.symlink_to(цель, target_is_directory=True)
                            подмены.append(True)
                        if подмены and имя == абсолютный:
                            чтения_цели.append('абсолютное открытие после подмены')
                            raise ПредотвращеноЧтениеЦели()
                    return штатное_открытие(путь, флаги, *аргументы, **ключи)
                def поток(путь, режим='r', *аргументы, **ключи):
                    имя = os.fspath(путь) if isinstance(путь, (str, bytes, os.PathLike)) else None
                    if подмены and isinstance(имя, str) and имя.startswith(os.fspath(журнал) + '/'):
                        чтения_цели.append('поток через подменённый предок')
                        raise ПредотвращеноЧтениеЦели()
                    return штатный_поток(путь, режим, *аргументы, **ключи)
                def читать(fd, размер):
                    сведения = os.fstat(fd)
                    if (сведения.st_dev, сведения.st_ino) in метки_целей:
                        чтения_цели.append('чтение синтетической цели')
                        raise ПредотвращеноЧтениеЦели()
                    return штатное_чтение(fd, размер)
                def читать_по_позиции(fd, размер, позиция):
                    сведения = os.fstat(fd)
                    if (сведения.st_dev, сведения.st_ino) in метки_целей:
                        чтения_цели.append('чтение синтетической цели по позиции')
                        raise ПредотвращеноЧтениеЦели()
                    return штатный_pread(fd, размер, позиция)
                with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                                       return_value=contextlib.nullcontext(lambda: None)), \
                     mock.patch.object(os, 'open', side_effect=открыть), \
                     mock.patch.object(os, 'read', side_effect=читать), \
                     mock.patch.object(os, 'pread', side_effect=читать_по_позиции), \
                     mock.patch.object(io, 'open', side_effect=поток), \
                     mock.patch.object(os, 'replace', wraps=os.replace) as замена:
                    try:
                        сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
                    except (сам.модуль.ОшибкаОтчёта, ПредотвращеноЧтениеЦели):
                        pass
                    else:
                        сам.fail('подмена предка не отклонена')
                сам.assertEqual(подмены, [True])
                сам.assertEqual(чтения_цели, [])
                сам.assertEqual(len(открытия), номер)
                сам.assertTrue(all(флаги & os.O_NOFOLLOW and флаги & os.O_NONBLOCK
                                   for флаги in открытия))
                замена.assert_not_called()
                сам.assertTrue(журнал.is_symlink())
                исходный = сохранённый / отчёт.parent.name / отчёт.name
                сам.assertEqual(исходный.read_bytes(), сам.старый)

    def test_подмена_сессии_между_проверкой_и_resolve_не_читает_другую(сам):
        import io

        корень, сессия, отчёт, путь_записи, запись = сам._синтетическая_сессия()
        запрос = корень / сессия
        исходная_папка = запрос.parent
        сохранённая = исходная_папка.with_name('сохранённая-сессия')
        другая_сессия = 'Журнал/2026-09-16_00-00-00_MSK_другая/запрос.md'
        другой_запрос = корень / другая_сессия
        другой_запрос.parent.mkdir()
        другой_запрос.write_bytes(b'synthetic request')
        другой_отчёт = другой_запрос.with_name('отчёт.md')
        другой_отчёт.write_bytes(сам.старый)
        другие_записи = другой_запрос.parent / 'материалы/запуски-проверок'
        другие_записи.mkdir(parents=True)
        другая_запись = другие_записи / путь_записи.name
        запись['сессия'] = другая_сессия
        другая_запись.write_text(json.dumps(запись, ensure_ascii=False) + '\n', encoding='utf-8')
        метки_целей = {
            (сведения.st_dev, сведения.st_ino)
            for сведения in (другой_запрос.parent.stat(), другие_записи.stat())
        }
        штатный_resolve = Path.resolve
        штатное_открытие = os.open
        штатный_поток = io.open
        подмены, попытки_чтения = [], []
        class ПредотвращеноЧтениеДругойСессии(Exception):
            pass
        def разрешить(путь, *аргументы, **ключи):
            if путь == запрос and not подмены:
                исходная_папка.rename(сохранённая)
                исходная_папка.symlink_to(другой_запрос.parent, target_is_directory=True)
                подмены.append(True)
            return штатный_resolve(путь, *аргументы, **ключи)
        def открыть(путь, флаги, *аргументы, **ключи):
            имя = os.fspath(путь) if isinstance(путь, (str, bytes, os.PathLike)) else None
            fd = ключи.get('dir_fd')
            метка_каталога = os.fstat(fd) if fd is not None else None
            другой_каталог = (метка_каталога is not None and
                              (метка_каталога.st_dev, метка_каталога.st_ino) in метки_целей)
            if подмены and (
                имя in (os.fspath(другой_отчёт), os.fspath(другая_запись))
                or другой_каталог and имя in (другой_отчёт.name, другая_запись.name)
            ):
                попытки_чтения.append('открытие другой сессии')
                raise ПредотвращеноЧтениеДругойСессии()
            return штатное_открытие(путь, флаги, *аргументы, **ключи)
        def поток(путь, режим='r', *аргументы, **ключи):
            имя = os.fspath(путь) if isinstance(путь, (str, bytes, os.PathLike)) else None
            if подмены and имя in (os.fspath(другой_отчёт), os.fspath(другая_запись)):
                попытки_чтения.append('поток другой сессии')
                raise ПредотвращеноЧтениеДругойСессии()
            return штатный_поток(путь, режим, *аргументы, **ключи)
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                               return_value=contextlib.nullcontext(lambda: None)), \
             mock.patch.object(Path, 'resolve', new=разрешить), \
             mock.patch.object(os, 'open', side_effect=открыть), \
             mock.patch.object(io, 'open', side_effect=поток), \
             mock.patch.object(os, 'replace', wraps=os.replace) as замена:
            try:
                сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
            except (сам.модуль.ОшибкаОтчёта, ПредотвращеноЧтениеДругойСессии):
                pass
            else:
                сам.fail('подмена сессии не отклонена')
        сам.assertEqual(подмены, [True])
        сам.assertEqual(попытки_чтения, [])
        замена.assert_not_called()
        сам.assertTrue(исходная_папка.is_symlink())
        сам.assertEqual((сохранённая / отчёт.name).read_bytes(), сам.старый)

    def test_обычные_пути_сессии_после_проверки_разрешаются_без_подмены(сам):
        корень, сессия, отчёт, путь_записи, _ = сам._синтетическая_сессия()
        запрос = корень / сессия
        ссылка_на_корень = сам.отчёт.parent / 'ссылка-на-корень'
        ссылка_на_корень.symlink_to(корень, target_is_directory=True)
        варианты = (
            (корень, Path(сессия)),
            (корень, запрос),
            (ссылка_на_корень, Path(сессия)),
            (корень, Path('Журнал') / 'ненужная' / '..' / запрос.parent.name / запрос.name),
        )
        for входной_корень, входной_запрос in варианты:
            with сам.subTest(входной_корень=входной_корень, входной_запрос=входной_запрос):
                результат = сам.модуль.разрешить_сессию(входной_корень, входной_запрос)
                сам.assertEqual(результат, (корень, запрос, отчёт, путь_записи.parent, сессия))

    def test_другой_родитель_writer_отклоняется_до_чтения_отчёта(сам):
        корень, сессия, отчёт, путь_записи, _ = сам._синтетическая_сессия()
        журнал = корень / 'Журнал'
        сохранённый = корень / 'сохранённый-журнал'
        цель = корень / 'синтетическая-цель'
        цель_сессии = цель / отчёт.parent.name
        цель_записей = цель_сессии / 'материалы' / 'запуски-проверок'
        цель_записей.mkdir(parents=True)
        цель_отчёта = цель_сессии / отчёт.name
        цель_отчёта.write_bytes(сам.старый)
        (цель_записей / путь_записи.name).write_bytes(b'synthetic history')
        метка = цель_отчёта.stat()
        штатные_родители = сам.модуль._ВладелецЗаменыПредпросмотра._открыть_родителей
        штатный_pread = os.pread
        чтения_цели, подмены = [], []
        def открыть_родителей(владелец):
            журнал.rename(сохранённый)
            цель.rename(журнал)
            подмены.append(True)
            return штатные_родители(владелец)
        def читать(fd, размер, позиция):
            сведения = os.fstat(fd)
            if (сведения.st_dev, сведения.st_ino) == (метка.st_dev, метка.st_ino):
                чтения_цели.append(True)
                raise AssertionError('недопустимое чтение другого родителя')
            return штатный_pread(fd, размер, позиция)
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                               return_value=contextlib.nullcontext(lambda: None)), \
             mock.patch.object(сам.модуль._ВладелецЗаменыПредпросмотра, '_открыть_родителей',
                               new=открыть_родителей), \
             mock.patch.object(os, 'pread', side_effect=читать), \
             mock.patch.object(os, 'replace', wraps=os.replace) as замена:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
        сам.assertEqual(подмены, [True])
        сам.assertEqual(чтения_цели, [])
        замена.assert_not_called()
        владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertIsNone(владелец._исходный)
        сам.assertEqual((сохранённый / отчёт.parent.name / отчёт.name).read_bytes(), сам.старый)

    def test_неизвестное_закрытие_каталога_не_разрешает_повтор(сам):
        корень, сессия, отчёт, _, _ = сам._синтетическая_сессия()
        штатное_закрытие = os.close
        закрытия = []
        ошибка = OSError(errno.EIO, 'потерян результат закрытия каталога')
        def закрыть(fd):
            владельцы = сам.модуль._ЗакреплённыеКаталогиПредпросмотра._удерживаемые
            if владельцы and fd == владельцы[-1]._родитель and замена.call_count:
                штатное_закрытие(fd)
                закрытия.append(fd)
                raise ошибка
            штатное_закрытие(fd)
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                               return_value=contextlib.nullcontext(lambda: None)), \
             mock.patch.object(os, 'replace', wraps=os.replace) as замена, \
             mock.patch.object(os, 'close', side_effect=закрыть) as закрытие:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта) as итог:
                сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
            with mock.patch.object(os, 'open') as открытие:
                with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'предыдущая опора'):
                    сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
        сам.assertIs(итог.exception.__cause__, ошибка)
        сам.assertEqual(len(закрытия), 1)
        сам.assertEqual(замена.call_count, 1)
        открытие.assert_not_called()
        владелец = сам.модуль._ЗакреплённыеКаталогиПредпросмотра._удерживаемые[-1]
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertIs(владелец.ошибка, ошибка)
        with mock.patch.object(os, 'open') as открыть, \
             mock.patch.object(os, 'close') as закрыть, \
             mock.patch.object(os, 'read') as читать, \
             mock.patch.object(os, 'listdir') as перечислить:
            for операция in (владелец._имена_записей, владелец._закрыть_все,
                             владелец.история, владелец.отчёт):
                with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                    операция()
        открыть.assert_not_called()
        закрыть.assert_not_called()
        читать.assert_not_called()
        перечислить.assert_not_called()
        сам.assertTrue(отчёт.exists())

    def test_известный_дефицит_fd_отказывает_и_разрешает_следующий_предпросмотр(сам):
        for код in (errno.EMFILE, errno.ENFILE):
            with сам.subTest(код=код):
                корень, сессия, отчёт, путь_записи, _ = сам._синтетическая_сессия()
                штатное_открытие = os.open
                попытки, владельцы = [], []
                def открыть(имя, флаги, *аргументы, **ключи):
                    опоры = сам.модуль._ЗакреплённыеКаталогиПредпросмотра._удерживаемые
                    if (имя == путь_записи.name and опоры
                        and ключи.get('dir_fd') == опоры[-1]._запуски):
                        попытки.append(True)
                        владельцы.append(опоры[-1])
                        raise OSError(код, 'модель отказа до open')
                    return штатное_открытие(имя, флаги, *аргументы, **ключи)
                with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                                       return_value=contextlib.nullcontext(lambda: None)), \
                     mock.patch.object(os, 'open', side_effect=открыть), \
                     mock.patch.object(os, 'replace', wraps=os.replace) as замена:
                    with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'нет свободного дескриптора'):
                        сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
                    замена.assert_not_called()
                сам.assertEqual(попытки, [True])
                сам.assertEqual(владельцы[0].состояние, 'отказ до чтения')
                сам.assertTrue(all(ресурс['фаза'] in ('закрыта', 'отказ')
                                   and ресурс['дескриптор'] is None
                                   for ресурс in владельцы[0]._ресурсы))
                сам.assertEqual(отчёт.read_bytes(), сам.старый)
                with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                                       return_value=contextlib.nullcontext(lambda: None)):
                    сам.assertEqual(сам.модуль.выполнить_предпросмотр(корень, Path(сессия)), 0)
                сам.assertNotEqual(отчёт.read_bytes(), сам.старый)

