    def test_сбой_закрытия_при_известном_отказе_не_разрешает_повтор(сам):
        штатное_закрытие = os.close
        подтверждения = []
        ошибка = OSError(errno.EIO, 'потерян результат закрытия')
        def закрыть_и_потерять(fd):
            штатное_закрытие(fd)
            подтверждения.append(True)
            raise ошибка
        with mock.patch.object(os, 'close', side_effect=закрыть_и_потерять) as закрытие:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта) as исход:
                сам.модуль.заменить_управляемый_блок(
                    сам.отчёт, сам.блок, ожидаемые_байты=b'wrong', _сохранить_права=True)
            with mock.patch.object(os, 'open') as открытие:
                with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'предыдущий исход'):
                    сам.модуль.заменить_управляемый_блок(
                        сам.отчёт, сам.блок, ожидаемые_байты=сам.старый, _сохранить_права=True)
        владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
        сам.assertEqual(подтверждения, [True])
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertIs(владелец.ошибка, ошибка)
        сам.assertIsInstance(владелец.первичная, сам.модуль.ОшибкаОтчёта)
        сам.assertIsInstance(исход.exception.__cause__, ExceptionGroup)
        сам.assertEqual(len(исход.exception.__cause__.exceptions), 2)
        сам.assertIs(исход.exception.__cause__.exceptions[0], владелец.первичная)
        сам.assertIs(исход.exception.__cause__.exceptions[1], ошибка)
        закрытие.assert_called_once()
        открытие.assert_not_called()

