    def test_переопределённая_пометка_не_подменяет_прерывание(сам):
        class Прерывание(KeyboardInterrupt):
            def add_note(сам, заметка):
                raise RuntimeError('ошибка добавления пометки')
        прерывание = Прерывание('прервано')
        штатная_замена = os.replace
        def заменить_и_прервать(*аргументы, **ключи):
            штатная_замена(*аргументы, **ключи)
